using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Bag of Beans (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class BagOfBeans2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("bag-of-beans", null, 0, MagicItemType.WondrousItem, ItemRarity.Rare, false, ContentSource.Srd51,
			null,
			("Borsa dei fagioli magici", "Oggetto meraviglioso, raro",
			"Questa borsa di stoffa robusta contiene 3d4 fagioli secchi. La borsa pesa 250 grammi, più 125 grammi per ogni fagiolo presente al suo interno.\n\nSe i fagioli vengono gettati a terra, generano un'esplosione in un raggio di 3 metri centrata sui fagioli stessi. Ogni creatura presente nell'area, incluso il possessore della borsa, deve effettuare un tiro salvezza su Destrezza con CD 15; in caso di fallimento, subisce 5d4 danni da fuoco, o la metà dei danni in caso di successo. Il fuoco incendia ogni oggetto infiammabile non indossato o trasportato presente nell'area.\n\nSe un fagiolo viene prelevato dalla borsa, piantato nel terriccio o nella sabbia e innaffiato, dopo 1 minuto genera un effetto nel luogo in cui è stato piantato. Il GM può scegliere l'effetto dalla tabella seguente, determinarlo casualmente o crearne uno personalmente.\n\n| d100 | Effetto |\n|---|---|\n| 01 | Spuntano 5d4 funghi velenosi. Se una creatura mangia un fungo, si tira un dado. Se il risultato del tiro è dispari, tale creatura deve superare un tiro salvezza su Costituzione con CD 15, altrimenti subisce 5d6 danni da veleno e diventa avvelenata per 1 ora. Se il risultato è pari, la creatura che ha mangiato il fungo ottiene 5d6 punti ferita temporanei per 1 ora. |\n| 02–10 | Scaturisce un geyser che spruzza una colonna alta 9 metri di acqua, birra, succo di mirtillo, tè, aceto, vino od olio (a scelta del GM) per 1d12 round. |\n| 11–20 | Spunta un treant. C'è una probabilità del 50 percento che sia caotico malvagio e attacchi. |\n| 21–30 | Dal terreno emerge una statua di pietra animata ma immobile, con le sembianze del possessore della borsa, che pronuncia minacce verbali contro di lui. Se il possessore della borsa si allontana dalla statua, quando sopraggiungono altre creature, quest'ultima descrive loro il possessore come il più scellerato dei nemici e fornisce loro le informazioni per trovarlo e attaccarlo. Se il possessore si trova sullo stesso piano di esistenza della statua, questa conosce la sua posizione. La statua diventa inanimata dopo 24 ore. |\n| 31–40 | Dal terreno si sprigiona un fuoco da campo azzurrognolo che arde per 24 ore (o finché non viene spento). |\n| 41–50 | Spuntano dal terreno 1d6 + 6 boleti stridenti. |\n\n| d100 | Effetto |\n|---|---|\n| 51–60 | 1d4 + 8 rospi di colore rosa acceso si avvicinano. Non appena un rospo viene toccato, si trasforma in un mostro di taglia Grande o inferiore a scelta del GM. Il mostro permane per 1 minuto, poi scompare in uno sbuffo di fumo rosa brillante. |\n| 61–70 | Un bulette affamato esce dal terreno e attacca. |\n| 71–80 | Dal terreno cresce un albero da frutto da cui pendono 1d10 + 20 frutti, 1d8 dei quali hanno gli effetti di pozioni magiche determinate casualmente, mentre uno ha l'effetto di un veleno da ingestione a scelta del GM. L'albero svanisce dopo 1 ora. I frutti raccolti rimangono e conservano gli eventuali poteri magici per 30 giorni. |\n| 81–90 | Dal terreno spunta un nido contenente 1d4 + 3 uova. Una creatura che mangia un uovo deve effettuare un tiro salvezza su Costituzione con CD 20: in caso di successo, il suo punteggio di caratteristica più basso aumenta permanentemente di 1 (in caso di più caratteristiche con lo stesso punteggio più basso, se ne sceglie una casualmente). Se lo fallisce, la creatura subisce invece 10d6 danni da forza causati da un'esplosione magica interna. |\n| 91–99 | Una piramide a base quadrata con lato di 18 metri emerge dal terreno. Al suo interno si trova un sarcofago contenente un signore delle mummie. La piramide è considerata la tana del signore delle mummie e il suo sarcofago contiene un tesoro determinato dal GM. |\n| 00 | Dal terreno si innalza una gigantesca pianta di fagioli che sale fino a un'altezza determinata dal GM. La sommità della pianta conduce in un luogo scelto dal GM, che può essere uno straordinario punto di osservazione, il castello di un gigante delle nuvole o un piano di esistenza diverso. |", null),
			("Bag of Beans", "Wondrous item, rare",
			"Inside this heavy cloth bag are 3d4 dry beans. The bag weighs 1/2 pound plus 1/4 pound for each bean it contains.\n\nIf you dump the bag's contents out on the ground,  they explode in a 10-foot radius, extending from the beans. Each creature in the area, including you, must  make a DC 15 Dexterity saving throw, taking 5d4 fire  damage on a failed save, or half as much damage on  a successful one. The fire ignites flammable objects  in the area that aren't being worn or carried.\n\nIf you remove a bean from the bag, plant it in dirt  or sand, and then water it, the bean produces an  effect 1 minute later from the ground where it was  planted. The GM can choose an effect from the  following table, determine it randomly, or create an  effect.\n\n| d100 | Effect |\n|---|---|\n| 01 | 5d4 toadstools sprout. If a creature eats a toadstool, roll any die. On an odd roll, the eater must succeed on a DC 15 Constitution saving throw or take 5d6 poison damage and become poisoned for 1 hour. On an even roll, the eater gains 5d6 temporary hit points for 1 hour. |\n| 02-10 | A geyser erupts and spouts water, beer, berry juice, tea, vinegar, wine, or oil (GM's choice) 30 feet into the air for 1d12 rounds. |\n| 11-20 | A treant sprouts. There's a 50 percent chance that the treant is chaotic evil and attacks. |\n| 21-30 | An animate, immobile stone statue in your likeness rises. It makes verbal threats against you. If you leave it and others come near, it describes you as the most heinous of villains and directs the newcomers to find and attack you. If you are on the same plane of existence as the statue, it knows where you are. The statue becomes inanimate after 24 hours. |\n| 31-40 | A campfire with blue flames springs forth and burns for 24 hours (or until it is extinguished). |\n| 41-50 | 1d6 + 6 shriekers sprout |\n| 51-60 | 1d4 + 8 bright pink toads crawl forth. Whenever a toad is touched, it transforms into a Large or smaller monster of the GM's choice. The monster remains for 1 minute, then disappears in a puff of bright pink smoke. |\n| 61-70 | A hungry bulette burrows up and attacks. |\n| 71-80 | A fruit tree grows. It has 1d10 + 20 fruit, 1d8 of which act as randomly determined magic potions, while one acts as an ingested poison of the GM's choice. The tree vanishes after 1 hour. Picked fruit remains, retaining any magic for 30 days. |\n| 81-90 | A nest of 1d4 + 3 eggs springs up. Any creature that eats an egg must make a DC 20 Constitution saving throw. On a successful save, a creature permanently increases its lowest ability score by 1, randomly choosing among equally low scores. On a failed save, the creature takes 10d6 force damage from an internal magical explosion. |\n| 91-99 | A pyramid with a 60-foot-square base bursts upward. Inside is a sarcophagus containing a mummy lord. The pyramid is treated as the mummy lord's lair, and its sarcophagus contains treasure of the GM's choice. |\n| 100 | A giant beanstalk sprouts, growing to a height of the GM's choice. The top leads where the GM chooses, such as to a great view, a cloud giant's castle, or a different plane of existence. |", null));
	}
}
